    @mcp.tool(
        annotations=ToolAnnotations(
            title="Register a business for Branded Calling",
            readOnlyHint=False,
            destructiveHint=True,
            openWorldHint=True,
        )
    )
    def branded_calling_create_branded_calling_enterprise(
        legal_name: str,
        doing_business_as: str,
        organization_type: Literal["commercial", "government", "non_profit"],
        organization_legal_type: Literal[
            "corporation", "llc", "partnership", "nonprofit", "other"
        ],
        country_code: str,
        jurisdiction_of_incorporation: str,
        website: str,
        fein: str,
        industry: str,
        number_of_employees: Literal[
            "1-10", "11-50", "51-200", "201-500", "501-2000", "2001-10000", "10001+"
        ],
        organization_contact: dict[str, Any] | None,
        billing_contact: dict[str, Any] | None,
        physical_address: dict[str, Any] | None,
        billing_address: dict[str, Any] | None,
    ) -> str:
        """Register a business for Branded Calling

        Stores the legal entity behind your caller identities. Nothing is filed with the
        carrier until the business's first identity passes review. Only businesses
        registered in the US or Canada qualify (a FEIN or Canadian equivalent is
        required); any other country returns `422`. Send an `Idempotency-Key` so a
        retry replays the original response instead of registering the business twice.

        Args:
            legal_name: Exactly as on the tax record. (required)
            doing_business_as: (required)
            organization_type: (required)
            organization_legal_type: (required)
            country_code: ISO 3166-1 alpha-2. US or CA. (required)
            jurisdiction_of_incorporation: State, province or country of registration. (required)
            website: (required)
            fein: US Federal Employer Identification Number (NN-NNNNNNN) or the Canadian equivalent. Stored encrypted; only the last four digits are ever returned. (required)
            industry: One of the carrier industry labels, e.g. technology, healthcare, retail, finance, legal, insurance, real estate, logistics, education. (required)
            number_of_employees: (required)
            organization_contact: Object with keys: firstName (string, required); lastName (string, required); email (string, required); jobTitle (string) - Required on organizationContact.; phoneNumber (string, required) - E.164 with a leading +. (required)
            billing_contact: Object with keys: firstName (string, required); lastName (string, required); email (string, required); jobTitle (string) - Required on organizationContact.; phoneNumber (string, required) - E.164 with a leading +. (required)
            physical_address: Object with keys: streetAddress (string, required); extendedAddress (string); city (string, required); administrativeArea (string, required) - State or province code (IL, ON).; postalCode (string, required); country (string, required) - ISO 3166-1 alpha-2 (US or CA). (required)
            billing_address: Object with keys: streetAddress (string, required); extendedAddress (string); city (string, required); administrativeArea (string, required) - State or province code (IL, ON).; postalCode (string, required); country (string, required) - ISO 3166-1 alpha-2 (US or CA). (required)"""
        client = _get_client()
        try:
            response = client.branded_calling.create_branded_calling_enterprise(
                legal_name=legal_name,
                doing_business_as=doing_business_as,
                organization_type=organization_type,
                organization_legal_type=organization_legal_type,
                country_code=country_code,
                jurisdiction_of_incorporation=jurisdiction_of_incorporation,
                website=website,
                fein=fein,
                industry=industry,
                number_of_employees=number_of_employees,
                organization_contact=organization_contact,
                billing_contact=billing_contact,
                physical_address=physical_address,
                billing_address=billing_address,
            )
            return _format_response(response)
        except Exception as e:
            return f"Error: {e}"

