    @mcp.tool(
        annotations=ToolAnnotations(
            title="Update agent settings",
            readOnlyHint=False,
            destructiveHint=True,
            openWorldHint=True,
        )
    )
    def business_agent_update_business_agent_settings(
        agent_id: str | None = None,
        rollout: dict[str, Any] | None = None,
        handoff: dict[str, Any] | None = None,
        followup: dict[str, Any] | None = None,
        ai_audience: Literal["EVERYONE", "ALLOWLISTED_ONLY"] | None = None,
        never_say_phrases: list[str] | None = None,
    ) -> str:
        """Update agent settings

        Partial update: fields you omit keep their value. `rollout.enabled: true` turns the agent
        on for new conversations; `false` stops it on every thread. Turning it on for `EVERYONE`
        needs a payment method on the Business Agent billable account (Meta accepts the call but
        delivers nothing without one); `ALLOWLISTED_ONLY` does not, which is how you test with a
        few numbers before billing. `never_say_phrases` replaces the whole list.

        Args:
            agent_id
            rollout: Object with keys: enabled (boolean, required)
            handoff: Object with keys: enabled (boolean, required); message (string); message_selection (one of: DEFAULT, AGENT, CUSTOM)
            followup: Object with keys: enabled (boolean, required); followup_interval_in_seconds (one of: 0, 300, 900, 1800, 3600, 7200, 28800, 86400); message (string)
            ai_audience
            never_say_phrases: Exact phrases the agent must never say; the full replacement list."""
        client = _get_client()
        try:
            response = client.business_agent.update_business_agent_settings(
                agent_id=agent_id,
                rollout=rollout,
                handoff=handoff,
                followup=followup,
                ai_audience=ai_audience,
                never_say_phrases=never_say_phrases,
            )
            return _format_response(response)
        except Exception as e:
            return f"Error: {e}"

