    @mcp.tool(
        annotations=ToolAnnotations(
            title="Update a Discord scheduled event",
            readOnlyHint=False,
            destructiveHint=True,
            openWorldHint=True,
        )
    )
    def discord_update_discord_scheduled_event(
        guild_id: str,
        event_id: str,
        account_id: str,
        name: str | None = None,
        description: str | None = None,
        starts_at: str | None = None,
        ends_at: str | None = None,
        location: str | None = None,
        status: Literal["scheduled", "active", "completed", "cancelled"] | None = None,
        image_data_uri: str | None = None,
    ) -> str:
        """Update a Discord scheduled event

        Patch any subset of fields. Passing `status: 'cancelled'` is how you
        cancel an event. Discord doesn't have a dedicated cancel endpoint,
        it's a status transition.

        Most status transitions Discord enforces (you can't go SCHEDULED →
        COMPLETED directly). The common consumer case is SCHEDULED → CANCELED.

        Args:
            guild_id: (required)
            event_id: (required)
            account_id: (required)
            name
            description
            starts_at
            ends_at
            location: For external events.
            status: Status transition. Most common: 'cancelled' to cancel an event.
            image_data_uri"""
        client = _get_client()
        try:
            response = client.discord.update_discord_scheduled_event(
                guild_id=guild_id,
                event_id=event_id,
                account_id=account_id,
                name=name,
                description=description,
                starts_at=starts_at,
                ends_at=ends_at,
                location=location,
                status=status,
                image_data_uri=image_data_uri,
            )
            return _format_response(response)
        except Exception as e:
            return f"Error: {e}"

