    @mcp.tool(
        annotations=ToolAnnotations(
            title="Manually start a workflow run",
            readOnlyHint=False,
            destructiveHint=True,
            openWorldHint=True,
        )
    )
    def workflows_trigger_workflow(
        workflow_id: str,
        to: str | None = None,
        conversation_id: str | None = None,
        text: str | None = None,
    ) -> str:
        """Manually start a workflow run

        Kick off a run without waiting for an inbound message (useful for testing). Target an existing conversation by `conversationId`, or (WhatsApp only) a phone number via `to` (a conversation is found or created). `text` seeds the run's `lastMessage` variable. The graph must be runnable.

        Args:
            workflow_id: (required)
            to: Recipient phone (WhatsApp only)
            conversation_id: An existing conversation to run in (required for non-WhatsApp workflows)
            text: Simulated inbound text, seeded as the run's lastMessage variable"""
        client = _get_client()
        try:
            response = client.workflows.trigger_workflow(
                workflow_id=workflow_id,
                to=to,
                conversation_id=conversation_id,
                text=text,
            )
            return _format_response(response)
        except Exception as e:
            return f"Error: {e}"

    @mcp.tool(
        annotations=ToolAnnotations(
            title="Start an API-triggered workflow",
            readOnlyHint=False,
            destructiveHint=True,
            openWorldHint=True,
        )
    )
    def workflows_trigger_api_call_workflow(
        workflow_id: str,
        conversation_id: str | None = None,
        contact_id: str | None = None,
        to: str | None = None,
        variables: dict[str, Any] | None = None,
    ) -> str:
        """Start an API-triggered workflow

        Starts a run of an active workflow whose trigger type is `api_call`. Pass exactly one target: `conversationId` (a conversation on the workflow's account), `contactId` (resolved to that contact's conversation on the workflow's account), or `to` (WhatsApp workflows only: a phone number, whose conversation is found or created). `variables` are merged over the standard run variables, so each key is available as `{{key}}`.

        Args:
            workflow_id: (required)
            conversation_id: A conversation on the workflow's account
            contact_id: A contact with a conversation on the workflow's account
            to: Recipient phone in E.164 (WhatsApp workflows only)
            variables: Seed variables, merged over the standard run variables"""
        client = _get_client()
        try:
            response = client.workflows.trigger_api_call_workflow(
                workflow_id=workflow_id,
                conversation_id=conversation_id,
                contact_id=contact_id,
                to=to,
                variables=variables,
            )
            return _format_response(response)
        except Exception as e:
            return f"Error: {e}"

